/**
 * Robust scroll helper that accounts for sticky bars appearing/disappearing during scroll.
 * Uses instant jump + delayed smooth correction to avoid layout-shift misses.
 */
function robustScrollTo(targetId: string) {
  const el = document.getElementById(targetId);
  if (!el) return;
  // First: instant jump to approximate position to trigger any layout shifts
  el.scrollIntoView({ behavior: 'instant', block: 'start' });
  // Second: after layout settles (sticky bars appear/disappear), smooth scroll to correct position
  requestAnimationFrame(() => {
    setTimeout(() => {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 50);
  });
}

function InlineCTA({ text, subtext, variant = 'primary', showTimer = false, countdown, scrollTarget }: { 
  text: string | React.ReactNode; 
  subtext?: string; 
  variant?: 'primary' | 'subtle'; 
  showTimer?: boolean;
  countdown?: { days?: number; hours: number; minutes: number; seconds: number };
  scrollTarget?: string;
}) {
  const scrollToShop = () => {
    const target = scrollTarget || 'adv-shop-section';
    robustScrollTo(target);
  };

  if (variant === 'subtle') {
    return (
      <div className="my-8 py-6 border-y border-[#e8e3dc]">
        <button 
          onClick={scrollToShop}
          className="group flex items-center gap-2 text-[#424680] font-medium hover:text-[#363a6b] transition-colors"
        >
          <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
          <span>{text}</span>
        </button>
        {subtext && (
          <p className="text-xs text-[#8a7668] mt-1.5 ml-6">{subtext}</p>
        )}
      </div>
    );
  }

  return (
    <div className="my-10 text-center">
      <button 
        onClick={scrollToShop}
        className="cta-primary text-base lg:text-lg px-10 py-4 w-full sm:w-auto"
      >
        {text}
      </button>
      {showTimer && countdown && (
        <div className="flex items-center justify-center gap-1.5 mt-3 text-xs text-[#e63946] font-medium">
          <Clock className="w-3 h-3" />
          <span className="tabular-nums">{formatTime(countdown.hours)}:{formatTime(countdown.minutes)}:{formatTime(countdown.seconds)}</span>
          <span className="text-[#8a7668]">left at this price</span>
        </div>
      )}
      {subtext && (
        <p className="text-xs text-[#8a7668] mt-2">{subtext}</p>
      )}
    </div>
  );
}

